function makeTask(id) {
  let state = "queued", progress = 0;
  return {
    id,
    start() { state = "running"; },
    tick() { if (state === "running") { progress = Math.min(100, progress + 25); if (progress >= 100) state = "succeeded"; } },
    poll() { return { id, state, progress }; }
  };
}
const t = makeTask("task_8f3a");
const snaps = [];
snaps.push(t.poll());
t.start(); snaps.push(t.poll());
t.tick(); snaps.push(t.poll());
t.tick(); t.tick(); t.tick(); snaps.push(t.poll());
console.log(snaps.map(s => `${s.id}:${s.state}@${s.progress}%`).join(" -> "));
